Selection Sort.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    for (int i = 0; i < a.length; i++) {
      int best = i;
      for (int j = i + 1; j < a.length; j++) if (a[j] < a[best]) best = j;
      int t = a[i];
      a[i] = a[best];
      a[best] = t;
    }
    return a;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Bubble Sort.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    for (int end = a.length - 1; end > 0; end--) {
      boolean changed = false;
      for (int j = 0; j < end; j++)
        if (a[j] > a[j + 1]) {
          int t = a[j];
          a[j] = a[j + 1];
          a[j + 1] = t;
          changed = true;
        }
      if (!changed) break;
    }
    return a;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Insertion Sorting.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    for (int i = 1; i < a.length; i++) {
      int key = a[i], j = i - 1;
      while (j >= 0 && a[j] > key) {
        a[j + 1] = a[j];
        j--;
      }
      a[j + 1] = key;
    }
    return a;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Merge Sorting.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    merge(a, new int[a.length], 0, a.length);
    return a;
  }

  private static void merge(int[] a, int[] tmp, int l, int r) {
    if (r - l <= 1) return;
    int m = l + (r - l) / 2;
    merge(a, tmp, l, m);
    merge(a, tmp, m, r);
    int i = l, j = m, k = l;
    while (i < m && j < r) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < m) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    System.arraycopy(tmp, l, a, l, r - l);
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Quick Sorting.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    quick(a, 0, a.length - 1, new Random(0));
    return a;
  }

  private static void quick(int[] a, int l, int r, Random random) {
    if (l >= r) return;
    int pick = l + random.nextInt(r - l + 1), t = a[pick];
    a[pick] = a[r];
    a[r] = t;
    int pivot = a[r], i = l;
    for (int j = l; j < r; j++)
      if (a[j] < pivot) {
        t = a[i];
        a[i] = a[j];
        a[j] = t;
        i++;
      }
    t = a[i];
    a[i] = a[r];
    a[r] = t;
    quick(a, l, i - 1, random);
    quick(a, i + 1, r, random);
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Recursive Bubble Sort.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    bubble(a, a.length);
    return a;
  }

  private static void bubble(int[] a, int n) {
    if (n <= 1) return;
    boolean changed = false;
    for (int i = 0; i < n - 1; i++)
      if (a[i] > a[i + 1]) {
        int t = a[i];
        a[i] = a[i + 1];
        a[i + 1] = t;
        changed = true;
      }
    if (changed) bubble(a, n - 1);
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}

Recursive Insertion Sort.source:
import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    insertion(a, a.length);
    return a;
  }

  private static void insertion(int[] a, int n) {
    if (n <= 1) return;
    insertion(a, n - 1);
    int key = a[n - 1], j = n - 2;
    while (j >= 0 && a[j] > key) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = key;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {5, -1, 2, 2, 0})));
  }
}
